import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.C4zpkcTP.js";const l=JSON.parse('{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result types returned when a payment is started.","frontmatter":{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result types returned when a payment is started."},"headers":[],"relativePath":"go-myanmar-payments/references/results.md","filePath":"go-myanmar-payments/references/results.md"}'),a={name:"go-myanmar-payments/references/results.md"};function c(n,e,s,i,m,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns a pointer to one of four structs from the root package <code>myanmarpayments</code>. Each implements <code>PaymentResult</code>, whose <code>Flow()</code> method returns a <code>PaymentFlow</code>, so a type switch or <code>Flow()</code> tells them apart. Fields a gateway did not provide are <code>&quot;&quot;</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>kbz.PWA()</code> and <code>wave.Initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Flow()</code></td><td><code>PaymentFlow</code></td><td><code>FlowRedirect</code></td></tr><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID, as sent to the gateway</td></tr><tr><td><code>URL</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>GatewayReference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>aya.Initiate()</code> and <code>cs.Initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Flow()</code></td><td><code>PaymentFlow</code></td><td><code>FlowForm</code></td></tr><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>Action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>Fields</code></td><td><code>[]FormField</code></td><td>The signed hidden fields in order. Post them unchanged</td></tr><tr><td><code>Enctype</code></td><td><code>string</code></td><td>The encoding the gateway expects: <code>multipart/form-data</code> (AYA) or <code>application/x-www-form-urlencoded</code> (CyberSource)</td></tr><tr><td><code>HTML()</code></td><td><code>string</code></td><td>A complete page that submits the form on load. Every value is HTML-escaped (<code>&quot;</code> as <code>&amp;#34;</code>, <code>&#39;</code> as <code>&amp;#39;</code>), so the page is byte-for-byte the same in every Laranex SDK</td></tr><tr><td><code>Field(name)</code></td><td><code>(string, bool)</code></td><td>One field&#39;s value</td></tr><tr><td><code>Values()</code></td><td><code>map[string]string</code></td><td>The fields as a map</td></tr></tbody></table><p><code>FormField</code> is a struct with <code>Name string</code> and <code>Value string</code>.</p><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>kbz.QR()</code>, <code>yoma.Initiate()</code> and <code>yoma.RenewQR()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Flow()</code></td><td><code>PaymentFlow</code></td><td><code>FlowQR</code></td></tr><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>QRString</code></td><td><code>string</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>QRImage</code></td><td><code>string</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>ExpiresAt</code></td><td><code>time.Time</code></td><td>When the QR stops being payable; the zero time when the gateway sets no limit</td></tr><tr><td><code>Reference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for this QR, used for status checks (Yoma <code>refLabel</code>, KBZ <code>prepay_id</code>)</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>QRImageDataURI(mimeType)</code></td><td><code>string</code></td><td><code>QRImage</code> as a data URI; <code>&quot;&quot;</code> as <code>mimeType</code> means <code>image/png</code>. <code>&quot;&quot;</code> when there is no image</td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>kbz.App()</code>. It encodes to JSON as <code>orderId</code>, <code>orderInfo</code>, <code>sign</code> and <code>signType</code>, the names the KBZ Pay SDK uses.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Flow()</code></td><td><code>PaymentFlow</code></td><td><code>FlowApp</code></td></tr><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>OrderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>Sign</code></td><td><code>string</code></td><td>The signature of <code>OrderInfo</code></td></tr><tr><td><code>SignType</code></td><td><code>string</code></td><td>The signature algorithm, <code>SHA256</code></td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response; left out of the JSON encoding</td></tr></tbody></table><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><p>A <code>string</code> type, so <code>payment.Flow() == &quot;redirect&quot;</code> works too.</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Type</th></tr></thead><tbody><tr><td><code>FlowRedirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>FlowForm</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>FlowQR</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>FlowApp</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table><p><code>Raw</code> values are decoded JSON: numbers are <code>json.Number</code>, never a <code>float64</code>. Use <code>json.Marshal(payment.Raw)</code> to log them.</p><p>Every result type is a plain struct, so you can build one in your own tests, e.g. <code>&amp;myanmarpayments.RedirectPayment{OrderID: &quot;ORDER_1&quot;, URL: &quot;https://…&quot;}</code>.</p>',20)])])}const y=t(a,[["render",c]]);export{l as __pageData,y as default};
